import numpy as np

rng = np.random.default_rng(7)

def diff_ci(a: np.ndarray, b: np.ndarray, iters: int = 10_000):
    n = len(a)
    diffs = []
    for _ in range(iters):
        ia = rng.integers(0, n, n)
        ib = rng.integers(0, n, n)
        diffs.append(b[ib].mean() - a[ia].mean())
    return np.percentile(diffs, [2.5, 97.5])

import math
from scipy.stats import norm

def n_for_margin(p: float, margin: float, conf: float = 0.95) -> int:
    z = norm.ppf(1 - (1 - conf) / 2)
    return math.ceil(z**2 * p * (1 - p) / margin**2)

print(n_for_margin(0.80, 0.03))

class FieldF1Metric(BaseMetric):
    def __init__(self, fields: list[str], threshold: float = 0.9):
        self.fields = fields
        self.threshold = threshold

    def measure(self, test_case: LLMTestCase) -> float:
        gold = json.loads(test_case.expected_output)
        pred = json.loads(test_case.actual_output)
        tp = sum(1 for f in self.fields if gold.get(f) is not None and pred.get(f) == gold.get(f))
        fp = sum(1 for f in self.fields if pred.get(f) is not None and pred.get(f) != gold.get(f))
        fn = sum(1 for f in self.fields if gold.get(f) is not None and pred.get(f) != gold.get(f))
        self.score = 2 * tp / (2 * tp + fp + fn) if tp + fp + fn else 1.0
        self.success = self.score >= self.threshold
        return self.score

from math import comb

def pass_hat_k(results: dict[str, list[bool]], k: int) -> float:
    per_task = [comb(sum(r), k) / comb(len(r), k) for r in results.values()]
    return sum(per_task) / len(per_task)

results = {
    "refund": [True, True, True, True],
    "address": [True, True, True, False],
}
print(pass_hat_k(results, 2))
